"""Contract: Attack Plan generated by Nemotron-3-Ultra. Frozen for Week 1."""

from typing import List, Optional
from pydantic import BaseModel, Field
from shipcheck.contracts.finding import VulnClass


class AttackStep(BaseModel):
    """Specific attack vector to be executed by the sandbox probe harness."""

    step_id: str = Field(..., description="Unique step identifier")
    finding_id: str = Field(..., description="Associated finding ID from triage")
    vuln_class: VulnClass = Field(..., description="Target vulnerability class")
    target_file: str = Field(..., description="Target file containing suspect sink")
    target_endpoint: str = Field(..., description="Target HTTP route or CLI target, e.g. /login or /export")
    http_method: str = Field(default="POST", description="HTTP method: GET, POST, PUT")
    payload_strategy: str = Field(
        ...,
        description="Exploit strategy, e.g. 'SQL injection bypass' or 'Command injection via IP parameter'",
    )
    expected_marker: str = Field(
        ...,
        description="Deterministic boolean marker that confirms the exploit (e.g. 'uid=', 'root:', '>1 rows')",
    )
    suggested_payloads: List[str] = Field(
        default_factory=list,
        description="Candidate payloads synthesized by Nemotron or grounded by Tavily",
    )


class AttackPlan(BaseModel):
    """Complete attack plan over the PR diff and triage findings."""

    plan_id: str = Field(..., description="Unique ID for this scan plan")
    commit_sha: str = Field(default="", description="Target commit SHA")
    summary: str = Field(default="", description="Executive summary of the attack surface")
    steps: List[AttackStep] = Field(
        default_factory=list,
        description="Ordered list of attack steps to fan out into sandboxes",
    )
